// Copies Northlight's brand from the application repository into the website:
// colours and fonts from docs/design/tokens.json, the mark and lockup from
// assets/brand, and the Newsreader display font from assets/fonts.
//
//   npm run sync-brand                          (app checkout at ../northlight or ../aural)
//   NORTHLIGHT_APP_DIR=path npm run sync-brand  (anywhere else)
//
// The generated files are committed, so the site builds without the app repository.
// Edit the brand in the app repository (docs/design/brand.md), then sync.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const site = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const candidates = [process.env.NORTHLIGHT_APP_DIR, '../northlight', '../aural']
	.filter(Boolean)
	.map((p) => path.resolve(site, p));
const app = candidates.find((p) => fs.existsSync(path.join(p, 'docs/design/tokens.json')));
if (!app) {
	console.error(`No Northlight checkout found (tried ${candidates.join(', ')}). Set NORTHLIGHT_APP_DIR.`);
	process.exit(1);
}

const tokens = JSON.parse(fs.readFileSync(path.join(app, 'docs/design/tokens.json'), 'utf8'));
const c = tokens.color;
const hex = (v) => v.toLowerCase();
const m = tokens.material;
// Token shadows are in px without units ("0 1 1 #00000080"); CSS needs them.
const shadow = (v) => v.replace(/(^|\s)(-?\d+(?:\.\d+)?)(?=\s)/g, (_, sp, n) => `${sp}${n === '0' ? '0' : `${n}px`}`).toLowerCase();

// Light mode is not in the app (it has one dark theme); these come from the brand
// guide's on-light colours: Peat ink and the darker Overcast of the on-light mark.
const light = {
	accentLow: '#dde5ec',
	accent: '#4f6a84',
	accentHigh: '#24364a',
	white: c.surface0,
	gray1: c.surface1,
	gray2: '#3a423b',
	gray3: '#5d655c',
	gray4: '#8f968c',
	gray5: '#cfd1c6',
	gray6: '#e8e5da',
	gray7: '#f1eedf',
	black: '#f7f5ec',
};

// Starlight's named colours (card icons, asides, badges) mapped to the brand's.
const hues = [
	['blue', hex(c.accent)],
	['orange', hex(c.warning)],
	['purple', hex(c.midiNote)],
	['green', hex(c.success)],
	['red', hex(c.record)],
];

const css = `/* Generated by scripts/sync-brand.mjs from the Northlight repository's
   docs/design/tokens.json (${tokens.meta.name}, v${tokens.meta.version}). Do not edit; edit the
   tokens there and run npm run sync-brand. */

@font-face {
	font-family: '${tokens.font.display.family}';
	src: url('/fonts/${tokens.font.display.file}') format('truetype');
	font-weight: 200 800;
	font-style: normal;
	font-display: swap;
}

:root {
	--nl-font-display: '${tokens.font.display.family}', Georgia, serif;
	--nl-font-ui: '${tokens.font.ui.family}', system-ui, sans-serif;
	--nl-font-mono: '${tokens.font.mono.family}', ui-monospace, monospace;
	--nl-canvas: ${hex(c.canvas)};
	--nl-moon: ${hex(c.textPrimary)};
	--nl-overcast: ${hex(c.accent)};
	--nl-rowan: ${hex(c.record)};
	--nl-straw: ${hex(c.warning)};
	--nl-sea-grass: ${hex(c.success)};
	--nl-heather: ${hex(c.midiNote)};

	/* Surfaces, lines and text, as in the app. */
	--nl-surface-0: ${hex(c.surface0)};
	--nl-surface-1: ${hex(c.surface1)};
	--nl-surface-2: ${hex(c.surface2)};
	--nl-surface-3: ${hex(c.surface3)};
	--nl-line-subtle: ${hex(c.lineSubtle)};
	--nl-line-strong: ${hex(c.lineStrong)};
	--nl-line-focus: ${hex(c.lineFocus)};
	--nl-text-primary: ${hex(c.textPrimary)};
	--nl-text-secondary: ${hex(c.textSecondary)};
	--nl-text-tertiary: ${hex(c.textTertiary)};
	--nl-accent-subtle: ${hex(c.accentSubtle)};
	--nl-accent-hover: ${hex(c.accentHover)};

	/* The primary button: moonlight, the one bright thing in a view. */
	--nl-primary: ${hex(c.primary)};
	--nl-primary-hover: ${hex(c.primaryHover)};
	--nl-primary-pressed: ${hex(c.primaryPressed)};
	--nl-text-on-primary: ${hex(c.textOnPrimary)};

	/* Material: panels are flat, controls are tactile (design system 2.4). */
	--nl-control-top: ${hex(m.controlTop)};
	--nl-control-bottom: ${hex(m.controlBottom)};
	--nl-control-highlight: ${hex(m.controlHighlight)};
	--nl-control-shadow: ${shadow(m.controlShadow)};
	--nl-pressed-inset: ${shadow(m.pressedInset)};
	--nl-groove: ${hex(m.groove)};
	--nl-groove-inset: ${shadow(m.grooveInset)};
	--nl-groove-lip: ${hex(m.grooveLip)};
	--nl-glow-accent: ${shadow(m.glowAccent)};
	--nl-readout-well: ${hex(m.readoutWell)};
	--nl-readout-text: ${hex(m.readoutText)};

	--nl-radius-sm: ${tokens.radius.sm}px;
	--nl-radius-md: ${tokens.radius.md}px;
	--nl-radius-lg: ${tokens.radius.lg}px;
	--nl-letter-spacing-caps: ${tokens.font.letterSpacingCaps}em;

	--sl-font: var(--nl-font-ui);
	--sl-font-mono: var(--nl-font-mono);
}

:root,
::backdrop {
	--sl-color-accent-low: ${hex(c.surface2)};
	--sl-color-accent: ${hex(c.accent)};
	--sl-color-accent-high: ${hex(c.accentHover)};
	--sl-color-white: ${hex(c.textPrimary)};
	--sl-color-gray-1: ${hex(c.textPrimary)};
	--sl-color-gray-2: ${hex(c.textSecondary)};
	--sl-color-gray-3: ${hex(c.textTertiary)};
	--sl-color-gray-4: ${hex(c.textDisabled)};
	--sl-color-gray-5: ${hex(c.surface3)};
	--sl-color-gray-6: ${hex(c.surface1)};
	--sl-color-black: ${hex(c.surface0)};
${hues.map(([sl, v]) => `\t--sl-color-${sl}: ${v};\n\t--sl-color-${sl}-high: ${v};\n\t--sl-color-${sl}-low: color-mix(in srgb, ${v} 18%, ${hex(c.surface0)});`).join('\n')}
}

:root[data-theme='light'],
[data-theme='light'] ::backdrop {
	--sl-color-accent-low: ${light.accentLow};
	--sl-color-accent: ${light.accent};
	--sl-color-accent-high: ${light.accentHigh};
	--sl-color-white: ${light.white};
	--sl-color-gray-1: ${light.gray1};
	--sl-color-gray-2: ${light.gray2};
	--sl-color-gray-3: ${light.gray3};
	--sl-color-gray-4: ${light.gray4};
	--sl-color-gray-5: ${light.gray5};
	--sl-color-gray-6: ${light.gray6};
	--sl-color-gray-7: ${light.gray7};
	--sl-color-black: ${light.black};
}
`;

const copy = (from, to) => {
	fs.mkdirSync(path.dirname(path.join(site, to)), { recursive: true });
	fs.copyFileSync(path.join(app, from), path.join(site, to));
	console.log(`  ${to}`);
};

fs.writeFileSync(path.join(site, 'src/styles/brand.css'), css);
console.log(`From ${app}:\n  src/styles/brand.css`);
copy('assets/brand/northlight-mark.svg', 'src/assets/mark.svg');
copy('assets/brand/northlight-mark-on-light.svg', 'src/assets/mark-light.svg');
copy('assets/brand/northlight-lockup.svg', 'src/assets/lockup-dark.svg');
copy('assets/brand/northlight-lockup-on-light.svg', 'src/assets/lockup-light.svg');
copy('assets/brand/northlight-mark.svg', 'public/favicon.svg');
copy('assets/brand/northlight-icon-256.png', 'public/apple-touch-icon.png');
copy(`assets/fonts/${tokens.font.display.file}`, `public/fonts/${tokens.font.display.file}`);
copy('assets/fonts/Newsreader-OFL.txt', 'public/fonts/Newsreader-OFL.txt');
